// WAF-JS stub engine (host build/inspection fixture).
//
// Exports the single inspection entry point and returns a well-formed allow
// finding. A reused transaction reports a block with skip_reason
// "transaction_reuse" so tests can detect state leaking between inspections.
globalThis.wafjsInspect = function (tx, request) {
	if (tx.inspected) {
		return {
			verdict: "block",
			anomaly_score: 0,
			matched_rule_ids: [],
			inspection_scope: [],
			body_inspected: false,
			skip_reason: "transaction_reuse",
			unsupported_features: []
		};
	}
	tx.inspected = true;
	tx.method = request.method;
	tx.rule_count = globalThis.wafjsRuleset ? globalThis.wafjsRuleset.length : -1;
	return {
		verdict: "allow",
		anomaly_score: 0,
		matched_rule_ids: [],
		inspection_scope: ["args", "headers", "cookies"],
		body_inspected: false,
		skip_reason: "",
		unsupported_features: []
	};
};
